mapper.select:
/* Attd07Mapper.countFullDayLeaveOn */
SELECT COUNT(*)
  FROM TB_USER_LEAVE_USE U
 WHERE U.CMPNY_CD      = #{cmpnyCd}
   AND U.SITE_CD       = #{siteCd}
   AND U.USER_CD       = #{userCd}
   AND U.LEAVE_STATUS  = 'CONFIRMED'
   AND U.DEL_YN        = 'N'
   AND U.USE_UNIT_TYPE = '00'
   AND U.START_DATE    <=  #{workYmd}
   AND U.END_DATE      >=  #{workYmd}

/* Attd07Mapper.selectMonthlyAttdList */ WITH RECURSIVE /* 1. 부서 트리 — 시작 노드부터 하위까지 */ node_tree AS ( SELECT N.CMPNY_CD , N.SITE_CD , N.NODE_CD , N.NODE_NM FROM TB_SITE_NODE N WHERE N.CMPNY_CD = #{gvCmpnyCd} AND N.SITE_CD = #{siteCd} AND N.NODE_CD = #{nodeCd}
UNION ALL
SELECT C.CMPNY_CD , C.SITE_CD , C.NODE_CD , C.NODE_NM FROM TB_SITE_NODE C INNER JOIN node_tree P ON C.CMPNY_CD = P.CMPNY_CD AND C.SITE_CD = P.SITE_CD AND C.PARENT_NODE_CD = P.NODE_CD
),
/* 2. 대상 사용자 */ target_user AS ( SELECT U.CMPNY_CD , U.SITE_CD , U.USER_CD , U.USER_ID , U.USER_NM , U.NODE_CD , U.AUTH_CD , U.EMPLOYMENT_TYPE , NT.NODE_NM FROM TB_USER U INNER JOIN node_tree NT ON U.CMPNY_CD = NT.CMPNY_CD AND U.SITE_CD = NT.SITE_CD AND U.NODE_CD = NT.NODE_CD WHERE U.CMPNY_CD = #{gvCmpnyCd} AND U.SITE_CD = #{siteCd} AND U.USE_YN = 'Y' AND U.WITHDRAWAL_DATE IS NULL
AND U.USER_NM LIKE CONCAT('%', #{userNm}, '%')
AND U.EMPLOYMENT_TYPE = 'DAILY'
AND (U.EMPLOYMENT_TYPE IS NULL OR U.EMPLOYMENT_TYPE <> 'DAILY')
),
/* 3. 해당 월 일자 펼치기 (workYm 포맷 'YYYY-MM' / 'YYYYMM' 모두 지원) */ month_days AS ( SELECT DATE_FORMAT( DATE_ADD( STR_TO_DATE(CONCAT(REPLACE(#{workYm}, '-', ''), '01'), '%Y%m%d'), INTERVAL (T.N - 1) DAY ), '%Y%m%d' ) AS WORK_YMD FROM ( SELECT 1 AS N UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9 UNION ALL SELECT 10 UNION ALL SELECT 11 UNION ALL SELECT 12 UNION ALL SELECT 13 UNION ALL SELECT 14 UNION ALL SELECT 15 UNION ALL SELECT 16 UNION ALL SELECT 17 UNION ALL SELECT 18 UNION ALL SELECT 19 UNION ALL SELECT 20 UNION ALL SELECT 21 UNION ALL SELECT 22 UNION ALL SELECT 23 UNION ALL SELECT 24 UNION ALL SELECT 25 UNION ALL SELECT 26 UNION ALL SELECT 27 UNION ALL SELECT 28 UNION ALL SELECT 29 UNION ALL SELECT 30 UNION ALL SELECT 31 ) T WHERE T.N <= DAY( LAST_DAY(STR_TO_DATE(CONCAT(REPLACE(#{workYm}, '-', ''), '01'), '%Y%m%d')) ) )
/* 4. 메인 — 사용자 × 일자 카르테시안 + 계획/근태 LEFT JOIN */ SELECT U.USER_CD AS userCd , U.USER_ID AS userId , U.USER_NM AS userNm , U.NODE_NM AS deptNm , U.AUTH_CD AS authCd , FNC_CMM_INFO_SRCH(U.CMPNY_CD, 'BAIM_VAL', U.AUTH_CD, 'COM005') AS authNm , U.EMPLOYMENT_TYPE AS employmentType
/* INSERT 시 프론트가 들고있어야 할 키 */ , U.CMPNY_CD AS cmpnyCd , U.SITE_CD AS siteCd , U.NODE_CD AS nodeCd , D.WORK_YMD AS workYmd
, DAYOFWEEK(STR_TO_DATE(D.WORK_YMD, '%Y%m%d')) - 1 AS dow
/* 근무계획 (스케줄 / 휴가 양쪽 LEFT JOIN) */ , WP.WORK_PLAN_CD AS workPlanCd , CASE WHEN LU.LEAVE_CD IS NOT NULL THEN 'LEAVE' WHEN SCH.SCH_CD IS NOT NULL THEN 'SCH' ELSE NULL END AS planType
/* 스케줄 정보 (1·2구간) — SCH_TYPE 은 현재본(SCHT), 시간값은 유효 버전(SCH) */ , SCHT.SCH_TYPE AS schType , SCH.FST_SCH_STR_TIME AS plan1Start , SCH.FST_SCH_END_TIME AS plan1End , SCH.FST_SCH_BRK_MIN AS plan1BreakMin , SCH.SEC_SCH_STR_TIME AS plan2Start , SCH.SEC_SCH_END_TIME AS plan2End , SCH.SEC_SCH_BRK_MIN AS plan2BreakMin
/* 휴가 정보 */ , LV.LEAVE_NM AS leaveNm
/* 근태 1차 */ , A1.ATTD_ID AS attd1Id , A1.CHECK_IN_DATE AS act1InDate , A1.CHECK_IN_TIME AS act1InTime , A1.CHECK_IN_METHOD AS act1InMethod , A1.CHECK_OUT_DATE AS act1OutDate , A1.CHECK_OUT_TIME AS act1OutTime , A1.CHECK_OUT_METHOD AS act1OutMethod
/* 근태 2차 */ , A2.ATTD_ID AS attd2Id , A2.CHECK_IN_DATE AS act2InDate , A2.CHECK_IN_TIME AS act2InTime , A2.CHECK_IN_METHOD AS act2InMethod , A2.CHECK_OUT_DATE AS act2OutDate , A2.CHECK_OUT_TIME AS act2OutTime , A2.CHECK_OUT_METHOD AS act2OutMethod
/* PRAFTA-017 - 구간별 외근 플래그. 구간 ATTD_ID 가 TB_USER_ATTD_GPS 에 존재하면 'Y'. */ , CASE WHEN A1.ATTD_ID IS NOT NULL AND EXISTS ( SELECT 1 FROM TB_USER_ATTD_GPS G1 WHERE G1.CMPNY_CD = A1.CMPNY_CD AND G1.ATTD_ID = A1.ATTD_ID ) THEN 'Y' ELSE 'N' END AS attd1OutsideYn , CASE WHEN A2.ATTD_ID IS NOT NULL AND EXISTS ( SELECT 1 FROM TB_USER_ATTD_GPS G2 WHERE G2.CMPNY_CD = A2.CMPNY_CD AND G2.ATTD_ID = A2.ATTD_ID ) THEN 'Y' ELSE 'N' END AS attd2OutsideYn
, SCH.PRE_FIXED_OT_STR_TIME AS preFixedOtStrTime , SCH.PRE_FIXED_OT_END_TIME AS preFixedOtEndTime , SCH.FIXED_OT_STR_TIME AS fixedOtStrTime , SCH.FIXED_OT_END_TIME AS fixedOtEndTime , CASE WHEN EXISTS ( SELECT 1 FROM TB_USER_LEAVE_USE LX WHERE LX.CMPNY_CD = U.CMPNY_CD AND LX.USER_CD = U.USER_CD AND LX.LEAVE_STATUS = 'CONFIRMED' AND LX.DEL_YN = 'N' AND ( ( LX.USE_UNIT_TYPE = '00' AND LX.START_DATE <= D.WORK_YMD AND LX.END_DATE >= D.WORK_YMD ) OR ( LX.USE_UNIT_TYPE <> '00' AND LX.START_DATE = D.WORK_YMD ) ) ) THEN 'Y' ELSE 'N' END AS fixedOtExemptYn , CAST(NULL AS CHAR(1)) AS fixedOtUnfulfilledYn , CAST(NULL AS SIGNED) AS fixedOtActMinutes
FROM target_user U CROSS JOIN month_days D
LEFT JOIN TB_USER_WORK_PLAN WP ON WP.CMPNY_CD = U.CMPNY_CD AND WP.SITE_CD = U.SITE_CD AND WP.USER_CD = U.USER_CD AND WP.WORK_YMD = D.WORK_YMD
/* 근무계획코드가 스케줄코드인 경우 — 근무일(WP.WORK_YMD) 기준 유효 스케줄(effective-dating) 적용. TB_SCH_MGMT(현재본) 과 TB_SCH_MGMT_HIST(전 버전)를 UNION 으로 합쳐 APPLY_DATE <= WORK_YMD 인 가장 최근 버전의 시간값을 결합한다. */ LEFT JOIN ( /* 현재본 + 이력본을 SCH_CD + APPLY_DATE 단위로 합친 유효 스케줄 후보. 동일 SCH_CD + APPLY_DATE 가 중복되면 HIST_IDX 최댓값 1건만 채택한다. */ SELECT E.CMPNY_CD , E.SITE_CD , E.SCH_CD , E.APPLY_DATE , E.FST_SCH_STR_TIME , E.FST_SCH_END_TIME , E.FST_SCH_BRK_MIN , E.SEC_SCH_STR_TIME , E.SEC_SCH_END_TIME , E.SEC_SCH_BRK_MIN , E.PRE_FIXED_OT_STR_TIME , E.PRE_FIXED_OT_END_TIME , E.FIXED_OT_STR_TIME , E.FIXED_OT_END_TIME FROM ( /* 현재본 (HIST_IDX 를 최댓값으로 두어 동일 APPLY_DATE 중복 시 현재본 우선) */ SELECT M.CMPNY_CD , M.SITE_CD , M.SCH_CD , M.APPLY_DATE , M.FST_SCH_STR_TIME , M.FST_SCH_END_TIME , M.FST_SCH_BRK_MIN , M.SEC_SCH_STR_TIME , M.SEC_SCH_END_TIME , M.SEC_SCH_BRK_MIN , M.PRE_FIXED_OT_STR_TIME , M.PRE_FIXED_OT_END_TIME , M.FIXED_OT_STR_TIME , M.FIXED_OT_END_TIME , 2147483647 AS HIST_IDX /* 사용중지(USE_YN='N') 근무타입도 이미 배정된 근무일에는 그대로 해석한다(신규 배정 가능 여부와 무관) — USE_YN 필터 없음 */ FROM TB_SCH_MGMT M
UNION ALL
/* 이력본 */ SELECT H.CMPNY_CD , H.SITE_CD , H.SCH_CD , H.APPLY_DATE , H.FST_SCH_STR_TIME , H.FST_SCH_END_TIME , H.FST_SCH_BRK_MIN , H.SEC_SCH_STR_TIME , H.SEC_SCH_END_TIME , H.SEC_SCH_BRK_MIN , H.PRE_FIXED_OT_STR_TIME , H.PRE_FIXED_OT_END_TIME , H.FIXED_OT_STR_TIME , H.FIXED_OT_END_TIME , H.HIST_IDX FROM TB_SCH_MGMT_HIST H ) E /* 동일 SCH_CD + APPLY_DATE 그룹에서 HIST_IDX 최댓값 행만 채택 */ WHERE E.HIST_IDX = ( SELECT MAX(E2.HIST_IDX) FROM ( SELECT M2.CMPNY_CD, M2.SITE_CD, M2.SCH_CD, M2.APPLY_DATE, 2147483647 AS HIST_IDX FROM TB_SCH_MGMT M2 UNION ALL SELECT H2.CMPNY_CD, H2.SITE_CD, H2.SCH_CD, H2.APPLY_DATE, H2.HIST_IDX FROM TB_SCH_MGMT_HIST H2 ) E2 WHERE E2.CMPNY_CD = E.CMPNY_CD AND E2.SITE_CD = E.SITE_CD AND E2.SCH_CD = E.SCH_CD AND E2.APPLY_DATE = E.APPLY_DATE ) ) SCH ON SCH.CMPNY_CD = WP.CMPNY_CD AND SCH.SITE_CD = WP.SITE_CD AND SCH.SCH_CD = WP.WORK_PLAN_CD /* 근무일 기준 APPLY_DATE <= WORK_YMD 인 가장 최근(MAX APPLY_DATE) 버전만 적용. 단, 근무일보다 늦게 적용 시작된 스케줄을 그 이전 날에 배정한 경우(상한 충족 버전 없음)엔 "스케줄 없음" 대신 최이른 적용버전(MIN APPLY_DATE)으로 폴백한다. */ AND SCH.APPLY_DATE = ( SELECT COALESCE( MAX(CASE WHEN SE.APPLY_DATE <= WP.WORK_YMD THEN SE.APPLY_DATE END) , MIN(SE.APPLY_DATE) ) FROM ( SELECT M3.CMPNY_CD, M3.SITE_CD, M3.SCH_CD, M3.APPLY_DATE FROM TB_SCH_MGMT M3 UNION ALL SELECT H3.CMPNY_CD, H3.SITE_CD, H3.SCH_CD, H3.APPLY_DATE FROM TB_SCH_MGMT_HIST H3 ) SE WHERE SE.CMPNY_CD = WP.CMPNY_CD AND SE.SITE_CD = WP.SITE_CD AND SE.SCH_CD = WP.WORK_PLAN_CD )
/* SCH_TYPE 은 이력본에 컬럼이 없으므로 항상 현재본(TB_SCH_MGMT)에서 가져온다. 사용중지 근무타입이어도 SCH_TYPE(1구간/2구간)은 그대로 필요하므로 USE_YN 필터를 걸지 않는다(2구간이 1구간처럼 렌더링되는 것 방지) */ LEFT JOIN TB_SCH_MGMT SCHT ON SCHT.CMPNY_CD = WP.CMPNY_CD AND SCHT.SITE_CD = WP.SITE_CD AND SCHT.SCH_CD = WP.WORK_PLAN_CD
/* prafta-com-008-E-2: 연차일/연차명을 work_plan(LEAVE_CD) 이 아니라 leave_use(LU) 오버레이로 산출. 그날 종일 확정 연차(USE_UNIT_TYPE='00') 1건을 매칭하고, 그 LEAVE_CD 로 종류명(LV)을 조인한다. */ LEFT JOIN TB_USER_LEAVE_USE LU ON LU.CMPNY_CD = U.CMPNY_CD AND LU.USER_CD = U.USER_CD AND LU.START_DATE = D.WORK_YMD AND LU.LEAVE_STATUS = 'CONFIRMED' AND LU.DEL_YN = 'N' AND LU.USE_UNIT_TYPE = '00' LEFT JOIN TB_LEAVE_TYPE_MGMT LV ON LV.CMPNY_CD = LU.CMPNY_CD AND LV.LEAVE_CD = LU.LEAVE_CD
/* 근태 1차 */ LEFT JOIN TB_USER_ATTD_MGMT A1 ON A1.CMPNY_CD = U.CMPNY_CD AND A1.SITE_CD = U.SITE_CD AND A1.USER_CD = U.USER_CD AND A1.WORK_YMD = D.WORK_YMD AND A1.WORK_SEQ = 1 AND A1.DEL_YN = 'N'
/* 근태 2차 */ LEFT JOIN TB_USER_ATTD_MGMT A2 ON A2.CMPNY_CD = U.CMPNY_CD AND A2.SITE_CD = U.SITE_CD AND A2.USER_CD = U.USER_CD AND A2.WORK_YMD = D.WORK_YMD AND A2.WORK_SEQ = 2 AND A2.DEL_YN = 'N'
ORDER BY U.USER_CD, D.WORK_YMD

/* Attd07Mapper.selectMonthlyAttdReqSummary */ WITH RECURSIVE /* 1. 부서 트리 — 시작 노드부터 하위까지 */ node_tree AS ( SELECT N.CMPNY_CD , N.SITE_CD , N.NODE_CD FROM TB_SITE_NODE N WHERE N.CMPNY_CD = #{gvCmpnyCd} AND N.SITE_CD = #{siteCd} AND N.NODE_CD = #{nodeCd}
UNION ALL
SELECT C.CMPNY_CD , C.SITE_CD , C.NODE_CD FROM TB_SITE_NODE C INNER JOIN node_tree P ON C.CMPNY_CD = P.CMPNY_CD AND C.SITE_CD = P.SITE_CD AND C.PARENT_NODE_CD = P.NODE_CD
)
SELECT A.REQ_ID AS reqId , A.WORK_YMD AS workYmd , A.USER_CD AS userCd FROM TB_USER_ATTD_REQ A WHERE A.CMPNY_CD = #{gvCmpnyCd} AND A.SITE_CD = #{siteCd} AND A.WORK_YMD LIKE CONCAT(REPLACE(#{workYm}, '-', ''), '%') AND A.DEL_YN = 'N' AND A.REQ_STATUS = '01'
AND COALESCE(NULLIF(A.NODE_CD, ''), ( SELECT U.NODE_CD FROM TB_USER U WHERE U.CMPNY_CD = A.CMPNY_CD AND U.SITE_CD = A.SITE_CD AND U.USER_CD = A.USER_CD LIMIT 1 )) IN (SELECT NT.NODE_CD FROM node_tree NT)

/* Attd07Mapper.selectMonthlyLeaveChangeReqSummary */
WITH RECURSIVE /* 1. 부서 트리 — 시작 노드부터 하위까지 */ node_tree AS ( SELECT N.CMPNY_CD , N.SITE_CD , N.NODE_CD FROM TB_SITE_NODE N WHERE N.CMPNY_CD = #{gvCmpnyCd} AND N.SITE_CD = #{siteCd} AND N.NODE_CD = #{nodeCd}
UNION ALL
SELECT C.CMPNY_CD , C.SITE_CD , C.NODE_CD FROM TB_SITE_NODE C INNER JOIN node_tree P ON C.CMPNY_CD = P.CMPNY_CD AND C.SITE_CD = P.SITE_CD AND C.PARENT_NODE_CD = P.NODE_CD
)
/* 2-1. 출발일(현재 연차 사용일) 기준 행 */ SELECT R.CHANGE_REQ_ID AS reqId , LU.START_DATE AS workYmd , R.TARGET_USER_CD AS userCd FROM TB_LEAVE_CHANGE_REQUEST R INNER JOIN TB_USER_LEAVE_USE LU ON LU.CMPNY_CD = R.CMPNY_CD AND LU.LEAVE_ID = R.TARGET_LEAVE_ID INNER JOIN TB_USER TU ON TU.CMPNY_CD = R.CMPNY_CD AND TU.SITE_CD = R.SITE_CD AND TU.USER_CD = R.TARGET_USER_CD INNER JOIN node_tree NT ON NT.CMPNY_CD = TU.CMPNY_CD AND NT.SITE_CD = TU.SITE_CD AND NT.NODE_CD = TU.NODE_CD WHERE R.CMPNY_CD = #{gvCmpnyCd} AND R.SITE_CD = #{siteCd} AND R.DEL_YN = 'N' AND R.REQ_STATUS IN ('REQUESTED', 'AGREED') AND LU.START_DATE LIKE CONCAT(REPLACE(#{workYm}, '-', ''), '%')
UNION ALL
/* 2-2. 이동 대상일 기준 행 (MOVE 만 — DELETE 는 MOVE_TARGET_DATE NULL 로 자동 제외) */ SELECT R.CHANGE_REQ_ID AS reqId , R.MOVE_TARGET_DATE AS workYmd , R.TARGET_USER_CD AS userCd FROM TB_LEAVE_CHANGE_REQUEST R INNER JOIN TB_USER TU ON TU.CMPNY_CD = R.CMPNY_CD AND TU.SITE_CD = R.SITE_CD AND TU.USER_CD = R.TARGET_USER_CD INNER JOIN node_tree NT ON NT.CMPNY_CD = TU.CMPNY_CD AND NT.SITE_CD = TU.SITE_CD AND NT.NODE_CD = TU.NODE_CD WHERE R.CMPNY_CD = #{gvCmpnyCd} AND R.SITE_CD = #{siteCd} AND R.DEL_YN = 'N' AND R.REQ_STATUS IN ('REQUESTED', 'AGREED') AND R.MOVE_TARGET_DATE LIKE CONCAT(REPLACE(#{workYm}, '-', ''), '%')

/* Attd07Mapper.selectAttdId */
SELECT CONCAT(DATE_FORMAT(NOW(), '%Y%m%d'), FNC_CMM_SEQ_NEXTVAL(#{gvCmpnyCd}, 'ATTD_ID')) AS attdId
FROM DUAL

/* Attd07Mapper.selectHistId */
SELECT CONCAT(DATE_FORMAT(NOW(), '%Y%m%d'), FNC_CMM_SEQ_NEXTVAL(#{gvCmpnyCd}, 'ATTD_HIST_ID')) AS histId
FROM DUAL

mapper.update:
    /* Attd07Mapper.updateUserAttdInfos */
    INSERT INTO TB_USER_ATTD_MGMT (
		ATTD_ID
		, CMPNY_CD
		, SITE_CD
		, USER_CD
		, WORK_YMD

		, NODE_CD
		, WORK_SEQ

		, CHECK_IN_DATE
		, CHECK_IN_TIME
		, CHECK_IN_METHOD
		, CHECK_OUT_DATE
		, CHECK_OUT_TIME
		, CHECK_OUT_METHOD

		, DEL_YN
		, INSERT_NO
		, INSERT_DATE
		, UPDATE_NO
		, UPDATE_DATE
	)
	VALUES (
		#{attdId}
		, #{gvCmpnyCd}
		, #{siteCd}
		, #{userCd}
		, #{workYmd}

		, #{nodeCd}
		, #{workSeq}

		, #{checkInDate}
		, #{checkInTime}
		, #{checkInMethod}
		, #{checkOutDate}
		, #{checkOutTime}
		, #{checkOutMethod}

		, 'N'
		, #{gvUserCd}
		, NOW()
		, #{gvUserCd}
		, NOW()
	) AS NEW
	ON DUPLICATE KEY UPDATE
		CHECK_IN_DATE		= NEW.CHECK_IN_DATE
		, CHECK_IN_TIME		= NEW.CHECK_IN_TIME
		, CHECK_IN_METHOD	= NEW.CHECK_IN_METHOD
		, CHECK_OUT_DATE	= NEW.CHECK_OUT_DATE
		, CHECK_OUT_TIME	= NEW.CHECK_OUT_TIME
		, CHECK_OUT_METHOD	= NEW.CHECK_OUT_METHOD
		, DEL_YN			= NEW.DEL_YN
		, UPDATE_NO			= NEW.UPDATE_NO
		, UPDATE_DATE		= NEW.UPDATE_DATE

mapper.insert:
    /* Attd07Mapper.insertUserAttdInfos */
    INSERT INTO TB_USER_ATTD_HIST (
		HIST_ID
		, CMPNY_CD
		, ATTD_ID
		, SITE_CD
		, HIST_TYPE

		, PROCESS_REASON
		, WORK_YMD

		, BEF_CHECK_IN_DATE
		, BEF_CHECK_IN_TIME
		, BEF_CHECK_OUT_DATE
		, BEF_CHECK_OUT_TIME

		, AFT_CHECK_IN_DATE
		, AFT_CHECK_IN_TIME
		, AFT_CHECK_OUT_DATE
		, AFT_CHECK_OUT_TIME

		, INSERT_NO
		, INSERT_DATE 
    )
    VALUES (
		#{histId}
		, #{gvCmpnyCd}
		, #{attdId}
		, #{siteCd}
		, #{histType}

		, #{processReason}
		, #{workYmd}

		, #{befCheckInDate}
		, #{befCheckInTime}
		, #{befCheckOutDate}
		, #{befCheckOutTime}

		, #{aftCheckInDate}
		, #{aftCheckInTime}
		, #{aftCheckOutDate}
		, #{aftCheckOutTime}

		, #{gvUserCd}
		, NOW()
	)

mapper.select:
/* Attd07Mapper.selectDailyAttdDetails */ SELECT A.CMPNY_CD AS cmpnyCd , A.USER_CD AS userCd , B.USER_ID AS userId , B.USER_NM AS userNm , B.EMPLOYMENT_TYPE AS employmentType , A.SITE_CD AS siteCd , B.NODE_CD AS nodeCd , A.WORK_YMD AS workYmd
/* 스케줄 정보 (1·2구간) — SCH_TYPE 은 현재본(SCHT), 시간값은 유효 버전(SCH) */ , SCHT.SCH_TYPE AS schType , SCH.FST_SCH_STR_TIME AS plan1Start , SCH.FST_SCH_END_TIME AS plan1End , SCH.FST_SCH_BRK_MIN AS plan1BreakMin , SCH.SEC_SCH_STR_TIME AS plan2Start , SCH.SEC_SCH_END_TIME AS plan2End , SCH.SEC_SCH_BRK_MIN AS plan2BreakMin
/* 근태 1차 */ , A1.ATTD_ID AS attd1Id , A1.CHECK_IN_DATE AS act1InDate , A1.CHECK_IN_TIME AS act1InTime , A1.CHECK_IN_METHOD AS act1InMethod , A1.CHECK_OUT_DATE AS act1OutDate , A1.CHECK_OUT_TIME AS act1OutTime , A1.CHECK_OUT_METHOD AS act1OutMethod
, A1.CHECK_IN_DATE AS oriAct1InDate , A1.CHECK_IN_TIME AS oriAct1InTime , A1.CHECK_OUT_DATE AS oriAct1OutDate , A1.CHECK_OUT_TIME AS oriAct1OutTime
/* 근태 2차 */ , A2.ATTD_ID AS attd2Id , A2.CHECK_IN_DATE AS act2InDate , A2.CHECK_IN_TIME AS act2InTime , A2.CHECK_IN_METHOD AS act2InMethod , A2.CHECK_OUT_DATE AS act2OutDate , A2.CHECK_OUT_TIME AS act2OutTime , A2.CHECK_OUT_METHOD AS act2OutMethod
, A2.CHECK_IN_DATE AS oriAct2InDate , A2.CHECK_IN_TIME AS oriAct2InTime , A2.CHECK_OUT_DATE AS oriAct2OutDate , A2.CHECK_OUT_TIME AS oriAct2OutTime
/* PRAFTA-011 - 구간별 외근 플래그. 해당 구간 ATTD_ID 로 TB_USER_ATTD_GPS 행이 존재하면 'Y', 없으면 'N'. GPS 테이블에 WORK_SEQ 가 없으므로 구간 구분은 ATTD_ID 로만 한다. */ , CASE WHEN A1.ATTD_ID IS NOT NULL AND EXISTS ( SELECT 1 FROM TB_USER_ATTD_GPS G1 WHERE G1.CMPNY_CD = A1.CMPNY_CD AND G1.ATTD_ID = A1.ATTD_ID ) THEN 'Y' ELSE 'N' END AS attd1OutsideYn , CASE WHEN A2.ATTD_ID IS NOT NULL AND EXISTS ( SELECT 1 FROM TB_USER_ATTD_GPS G2 WHERE G2.CMPNY_CD = A2.CMPNY_CD AND G2.ATTD_ID = A2.ATTD_ID ) THEN 'Y' ELSE 'N' END AS attd2OutsideYn
, SCH.PRE_FIXED_OT_STR_TIME AS preFixedOtStrTime , SCH.PRE_FIXED_OT_END_TIME AS preFixedOtEndTime , SCH.FIXED_OT_STR_TIME AS fixedOtStrTime , SCH.FIXED_OT_END_TIME AS fixedOtEndTime , CASE WHEN EXISTS ( SELECT 1 FROM TB_USER_LEAVE_USE LX WHERE LX.CMPNY_CD = A.CMPNY_CD AND LX.USER_CD = A.USER_CD AND LX.LEAVE_STATUS = 'CONFIRMED' AND LX.DEL_YN = 'N' AND ( ( LX.USE_UNIT_TYPE = '00' AND LX.START_DATE <= A.WORK_YMD AND LX.END_DATE >= A.WORK_YMD ) OR ( LX.USE_UNIT_TYPE <> '00' AND LX.START_DATE = A.WORK_YMD ) ) ) THEN 'Y' ELSE 'N' END AS fixedOtExemptYn , CAST(NULL AS CHAR(1)) AS fixedOtUnfulfilledYn , CAST(NULL AS SIGNED) AS fixedOtActMinutes FROM TB_USER_ATTD_MGMT A INNER JOIN TB_USER B ON ( A.CMPNY_CD = B.CMPNY_CD AND A.USER_CD = B.USER_CD )
LEFT JOIN TB_USER_WORK_PLAN WP ON WP.CMPNY_CD = A.CMPNY_CD AND WP.SITE_CD = A.SITE_CD AND WP.USER_CD = A.USER_CD AND WP.WORK_YMD = A.WORK_YMD
/* 근무계획코드가 스케줄코드인 경우 — 근무일(A.WORK_YMD) 기준 유효 스케줄(effective-dating) 적용. TB_SCH_MGMT(현재본) 과 TB_SCH_MGMT_HIST(전 버전)를 UNION 으로 합쳐 APPLY_DATE <= WORK_YMD 인 가장 최근 버전의 시간값을 결합한다. */ LEFT JOIN ( /* 현재본 + 이력본을 SCH_CD + APPLY_DATE 단위로 합친 유효 스케줄 후보. 동일 SCH_CD + APPLY_DATE 가 중복되면 HIST_IDX 최댓값 1건만 채택한다. */ SELECT E.CMPNY_CD , E.SITE_CD , E.SCH_CD , E.APPLY_DATE , E.FST_SCH_STR_TIME , E.FST_SCH_END_TIME , E.FST_SCH_BRK_MIN , E.SEC_SCH_STR_TIME , E.SEC_SCH_END_TIME , E.SEC_SCH_BRK_MIN
, E.PRE_FIXED_OT_STR_TIME , E.PRE_FIXED_OT_END_TIME , E.FIXED_OT_STR_TIME , E.FIXED_OT_END_TIME FROM ( /* 현재본 (HIST_IDX 를 최댓값으로 두어 동일 APPLY_DATE 중복 시 현재본 우선) */ SELECT M.CMPNY_CD , M.SITE_CD , M.SCH_CD , M.APPLY_DATE , M.FST_SCH_STR_TIME , M.FST_SCH_END_TIME , M.FST_SCH_BRK_MIN , M.SEC_SCH_STR_TIME , M.SEC_SCH_END_TIME , M.SEC_SCH_BRK_MIN , M.PRE_FIXED_OT_STR_TIME , M.PRE_FIXED_OT_END_TIME , M.FIXED_OT_STR_TIME , M.FIXED_OT_END_TIME , 2147483647 AS HIST_IDX /* 사용중지(USE_YN='N') 근무타입도 이미 배정된 근무일에는 그대로 해석한다 — USE_YN 필터 없음 */ FROM TB_SCH_MGMT M
UNION ALL
/* 이력본 */ SELECT H.CMPNY_CD , H.SITE_CD , H.SCH_CD , H.APPLY_DATE , H.FST_SCH_STR_TIME , H.FST_SCH_END_TIME , H.FST_SCH_BRK_MIN , H.SEC_SCH_STR_TIME , H.SEC_SCH_END_TIME , H.SEC_SCH_BRK_MIN , H.PRE_FIXED_OT_STR_TIME , H.PRE_FIXED_OT_END_TIME , H.FIXED_OT_STR_TIME , H.FIXED_OT_END_TIME , H.HIST_IDX FROM TB_SCH_MGMT_HIST H ) E /* 동일 SCH_CD + APPLY_DATE 그룹에서 HIST_IDX 최댓값 행만 채택 */ WHERE E.HIST_IDX = ( SELECT MAX(E2.HIST_IDX) FROM ( SELECT M2.CMPNY_CD, M2.SITE_CD, M2.SCH_CD, M2.APPLY_DATE, 2147483647 AS HIST_IDX FROM TB_SCH_MGMT M2 UNION ALL SELECT H2.CMPNY_CD, H2.SITE_CD, H2.SCH_CD, H2.APPLY_DATE, H2.HIST_IDX FROM TB_SCH_MGMT_HIST H2 ) E2 WHERE E2.CMPNY_CD = E.CMPNY_CD AND E2.SITE_CD = E.SITE_CD AND E2.SCH_CD = E.SCH_CD AND E2.APPLY_DATE = E.APPLY_DATE ) ) SCH ON SCH.CMPNY_CD = WP.CMPNY_CD AND SCH.SITE_CD = WP.SITE_CD AND SCH.SCH_CD = WP.WORK_PLAN_CD /* 근무일 기준 APPLY_DATE <= WORK_YMD 인 가장 최근(MAX APPLY_DATE) 버전만 적용. 단, 근무일보다 늦게 적용 시작된 스케줄을 그 이전 날에 배정한 경우(상한 충족 버전 없음)엔 "스케줄 없음" 대신 최이른 적용버전(MIN APPLY_DATE)으로 폴백한다. */ AND SCH.APPLY_DATE = ( SELECT COALESCE( MAX(CASE WHEN SE.APPLY_DATE <= WP.WORK_YMD THEN SE.APPLY_DATE END) , MIN(SE.APPLY_DATE) ) FROM ( SELECT M3.CMPNY_CD, M3.SITE_CD, M3.SCH_CD, M3.APPLY_DATE FROM TB_SCH_MGMT M3 UNION ALL SELECT H3.CMPNY_CD, H3.SITE_CD, H3.SCH_CD, H3.APPLY_DATE FROM TB_SCH_MGMT_HIST H3 ) SE WHERE SE.CMPNY_CD = WP.CMPNY_CD AND SE.SITE_CD = WP.SITE_CD AND SE.SCH_CD = WP.WORK_PLAN_CD )
/* SCH_TYPE 은 이력본에 컬럼이 없으므로 항상 현재본(TB_SCH_MGMT)에서 가져온다 */ LEFT JOIN TB_SCH_MGMT SCHT ON SCHT.CMPNY_CD = WP.CMPNY_CD AND SCHT.SITE_CD = WP.SITE_CD AND SCHT.SCH_CD = WP.WORK_PLAN_CD /* 사용중지 근무타입도 SCH_TYPE(구간 수)은 그대로 필요 — USE_YN 필터 없음(2구간이 1구간처럼 표시되는 것 방지) */
/* prafta-com-008-E-2: 연차-스케줄 모델 전환 — work_plan 은 항상 SCH_CD 이므로 LEAVE 조인(미사용) 제거. 일자상세의 확정 연차는 selectDailyConfirmedLeave(leave_use 기준)가 별도로 제공한다. */
/* 근태 1차 */ LEFT JOIN TB_USER_ATTD_MGMT A1 ON A.CMPNY_CD = A1.CMPNY_CD AND A.SITE_CD = A1.SITE_CD AND A.USER_CD = A1.USER_CD AND A.WORK_YMD = A1.WORK_YMD AND A1.WORK_SEQ = 1 AND A1.DEL_YN = 'N'
/* 근태 2차 */ LEFT JOIN TB_USER_ATTD_MGMT A2 ON A.CMPNY_CD = A2.CMPNY_CD AND A.SITE_CD = A2.SITE_CD AND A.USER_CD = A2.USER_CD AND A.WORK_YMD = A2.WORK_YMD AND A2.WORK_SEQ = 2 AND A2.DEL_YN = 'N' WHERE A.CMPNY_CD = #{gvCmpnyCd} AND A.SITE_CD = #{siteCd} AND A.WORK_YMD = #{workYmd}
AND A.ATTD_ID = #{attdId}
AND A.USER_CD = #{userCd} AND A.DEL_YN = 'N' AND A.WORK_SEQ = ( SELECT MIN(SUB.WORK_SEQ) FROM TB_USER_ATTD_MGMT SUB WHERE SUB.CMPNY_CD = A.CMPNY_CD AND SUB.SITE_CD = A.SITE_CD AND SUB.USER_CD = A.USER_CD AND SUB.WORK_YMD = A.WORK_YMD AND SUB.DEL_YN = 'N' )

/* Attd07Mapper.selectDailyLeaveChangeReq */
SELECT R.CHANGE_REQ_ID AS changeReqId , R.TARGET_LEAVE_ID AS targetLeaveId , R.INITIATOR_TYPE AS initiatorType , R.REQ_TYPE AS reqType , R.REQ_STATUS AS reqStatus , LU.START_DATE AS targetStartDate , R.MOVE_TARGET_DATE AS moveTargetDate , R.REQ_REASON AS reqReason , DATE_FORMAT(R.INSERT_DATE, '%Y%m%d%H%i%s') AS insertDate , LU.LEAVE_CD AS leaveCd , LT.LEAVE_NM AS leaveNm , LU.USE_UNIT_TYPE AS useUnitType , FNC_CMM_INFO_SRCH(R.CMPNY_CD, 'SYST_VAL', LU.USE_UNIT_TYPE, 'SYS025') AS unitNm , LU.START_TIME AS startTime , LU.END_TIME AS endTime
, CASE WHEN LU.REQ_ID IS NULL THEN LU.LEAVE_DAYS ELSE IFNULL( ( SELECT SUM(X.LEAVE_DAYS) FROM TB_USER_LEAVE_USE X WHERE X.CMPNY_CD = LU.CMPNY_CD AND X.REQ_ID = LU.REQ_ID AND X.LEAVE_STATUS = 'CONFIRMED' AND X.DEL_YN = 'N' ) , LU.LEAVE_DAYS ) END AS leaveDays FROM TB_LEAVE_CHANGE_REQUEST R INNER JOIN TB_USER_LEAVE_USE LU ON LU.CMPNY_CD = R.CMPNY_CD AND LU.LEAVE_ID = R.TARGET_LEAVE_ID LEFT JOIN TB_LEAVE_TYPE_MGMT LT ON LT.CMPNY_CD = LU.CMPNY_CD AND LT.LEAVE_CD = LU.LEAVE_CD WHERE R.CMPNY_CD = #{gvCmpnyCd} AND R.SITE_CD = #{siteCd} AND R.TARGET_USER_CD = #{userCd} AND R.DEL_YN = 'N' AND R.REQ_STATUS IN ('REQUESTED', 'AGREED') AND ( LU.START_DATE = #{workYmd} OR R.MOVE_TARGET_DATE = #{workYmd} ) ORDER BY R.INSERT_DATE DESC, R.CHANGE_REQ_ID DESC

/* Attd07Mapper.selectAttdWorkYmd */
SELECT M.WORK_YMD
  FROM TB_USER_ATTD_MGMT M
 WHERE M.CMPNY_CD = #{gvCmpnyCd}
   AND M.ATTD_ID  = #{attdId}
 LIMIT 1

/* Attd07Mapper.selectAttdSegmentsAroundDayExcept */
SELECT
      M.ATTD_ID         AS attdId
    , M.WORK_YMD        AS workYmd
    , M.WORK_SEQ        AS workSeq
    , M.CHECK_IN_DATE   AS checkInDate
    , M.CHECK_IN_TIME   AS checkInTime
    , M.CHECK_OUT_DATE  AS checkOutDate
    , M.CHECK_OUT_TIME  AS checkOutTime
  FROM TB_USER_ATTD_MGMT M
 WHERE M.CMPNY_CD = #{cmpnyCd}
   AND M.SITE_CD  = #{siteCd}
   AND M.USER_CD  = #{userCd}
   AND M.WORK_YMD BETWEEN #{fromYmd} AND #{toYmd}
   AND M.DEL_YN   = 'N'

   AND M.ATTD_ID != #{excludeAttdId}

