/* Attd07Mapper.dailyAttdDetailDelete */
UPDATE TB_USER_ATTD_MGMT
SET DEL_YN      = 'Y'
    , UPDATE_NO   = #{gvUserCd}
    , UPDATE_DATE = NOW()
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND SITE_CD  = #{siteCd}
  AND USER_CD  = #{userCd}
  AND ATTD_ID  = #{attdId}

/* Attd07Mapper.deleteOvertimeByAttdId */
UPDATE TB_USER_OVERTIME_MGMT
SET DEL_YN      = 'Y'
    , UPDATE_NO   = #{gvUserCd}
    , UPDATE_DATE = NOW()
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND SITE_CD  = #{siteCd}
  AND USER_CD  = #{userCd}
  AND ATTD_ID  = #{attdId}
  AND ATTD_ID IS NOT NULL
  AND DEL_YN   = 'N'

/* Attd07Mapper.deleteUserOvertimeById */
UPDATE TB_USER_OVERTIME_MGMT
SET DEL_YN      = 'Y'
    , UPDATE_NO   = #{updateNo}
    , UPDATE_DATE = NOW()
WHERE CMPNY_CD = #{cmpnyCd}
  AND SITE_CD  = #{siteCd}
  AND USER_CD  = #{userCd}
  AND OT_ID    = #{otId}
  AND DEL_YN   = 'N'
  AND OT_STATUS  <>  'CANCELLED'

/* Attd07Mapper.updateUserAttdReqApprove */
UPDATE TB_USER_ATTD_REQ
SET REQ_STATUS        = '02'
    , TARGET_ID       = #{targetId}
    , PROCESS_USER_CD = #{gvUserCd}
    , PROCESS_COMMENT = IFNULL(NULLIF(#{processComment}, ''), 'AUTO_APPROVED')
    , PROCESS_DATE    = NOW()
    , UPDATE_NO       = #{gvUserCd}
    , UPDATE_DATE     = NOW()
WHERE CMPNY_CD   = #{gvCmpnyCd}
  AND SITE_CD    = #{siteCd}
  AND REQ_ID     = #{reqId}
  AND DEL_YN     = 'N'
  AND REQ_STATUS = '01'

/* Attd07Mapper.updateUserAttdReqReject - PRAFTA-008 / PRAFTA-010 */
UPDATE TB_USER_ATTD_REQ
SET REQ_STATUS        = '03'
    , PROCESS_USER_CD = #{gvUserCd}
    , PROCESS_COMMENT = #{rejectReason}
    , PROCESS_DATE    = NOW()
    , UPDATE_NO       = #{gvUserCd}
    , UPDATE_DATE     = NOW()
WHERE CMPNY_CD   = #{gvCmpnyCd}
  AND SITE_CD    = #{siteCd}
  AND REQ_ID     = #{reqId}
  AND DEL_YN     = 'N'
  AND REQ_STATUS = '01'

/* Attd07Mapper.updateUserSchedModifyReqApprove */

UPDATE TB_USER_ATTD_REQ
SET REQ_STATUS        = '02'
    , PROCESS_USER_CD = #{gvUserCd}
    , PROCESS_COMMENT = #{processComment}
    , PROCESS_DATE    = NOW()
    , UPDATE_NO       = #{gvUserCd}
    , UPDATE_DATE     = NOW()
WHERE CMPNY_CD   = #{gvCmpnyCd}
  AND SITE_CD    = #{siteCd}
  AND REQ_ID     = #{reqId}
  AND DEL_YN     = 'N'
  AND REQ_STATUS = '01'

