/* Attd07Mapper.upsertUserWorkPlan - PRAFTA-APP-007 스케줄 수정(10) 승인 시 근무계획 한 칸 교체 (Attd05.saveUserWorkPlans 동형) */
INSERT INTO TB_USER_WORK_PLAN (
    CMPNY_CD
    , SITE_CD
    , USER_CD
    , WORK_YMD
    , WORK_PLAN_CD
    , INSERT_NO
    , INSERT_DATE
    , UPDATE_NO
    , UPDATE_DATE
) VALUES (
    #{gvCmpnyCd}
    , #{siteCd}
    , #{userCd}
    , #{workYmd}
    , #{workPlanCd}
    , #{gvUserCd}
    , NOW()
    , #{gvUserCd}
    , NOW()
) AS NEW
ON DUPLICATE KEY UPDATE
    WORK_PLAN_CD	= NEW.WORK_PLAN_CD
    , UPDATE_NO		= NEW.UPDATE_NO
    , UPDATE_DATE	= NOW()

/* Attd07Mapper.updateUserOvertimeReqApprove - 초과근무 요청 승인(요청 승인 관리 인박스 경유) */
UPDATE TB_USER_ATTD_REQ
SET REQ_STATUS        = '02'
    , PROCESS_USER_CD = #{gvUserCd}
    , PROCESS_COMMENT = 'OT_APPROVED'
    , PROCESS_DATE    = NOW()
    , UPDATE_NO       = #{gvUserCd}
    , UPDATE_DATE     = NOW()
WHERE CMPNY_CD   = #{gvCmpnyCd}
  AND SITE_CD    = #{siteCd}
  AND REQ_ID     = #{reqId}
  AND DEL_YN     = 'N'
  AND REQ_STATUS = '01'

