FROM TB_USER_ATTD_MGMT M
WHERE M.CMPNY_CD = #{gvCmpnyCd}
  AND M.SITE_CD  = #{siteCd}
  AND M.USER_CD  = #{userCd}
  AND M.WORK_YMD = #{workYmd}
  AND M.WORK_SEQ = #{workSeq}
  AND M.DEL_YN   = 'N'
LIMIT 1

/* Attd07Mapper.selectAttdIdByDay - PRAFTA-027: 초과근무 처리 이력 앵커용 그날 ATTD_ID */
SELECT M.ATTD_ID
FROM TB_USER_ATTD_MGMT M
WHERE M.CMPNY_CD = #{gvCmpnyCd}
  AND M.SITE_CD  = #{siteCd}
  AND M.USER_CD  = #{userCd}
  AND M.WORK_YMD = #{workYmd}
  AND M.DEL_YN   = 'N'
ORDER BY M.WORK_SEQ
LIMIT 1

/* Attd07Mapper.selectAllowedWindow */ SELECT SCH.FST_SCH_STR_TIME AS plan1Start , SCH.FST_SCH_END_TIME AS plan1End , SCH.SEC_SCH_STR_TIME AS plan2Start , SCH.SEC_SCH_END_TIME AS plan2End
/* 1st attd row - raw 출퇴근 일자/시각. 초과근무 등록 가능 범위는 "실근태 − 스케줄" 로 계산한다. */ , A1.CHECK_IN_DATE AS act1InDate , A1.CHECK_IN_TIME AS act1InTime , A1.CHECK_OUT_DATE AS act1OutDate , A1.CHECK_OUT_TIME AS act1OutTime
/* 2nd attd row - raw 출퇴근 일자/시각. */ , A2.CHECK_IN_DATE AS act2InDate , A2.CHECK_IN_TIME AS act2InTime , A2.CHECK_OUT_DATE AS act2OutDate , A2.CHECK_OUT_TIME AS act2OutTime
/* PRAFTA-FIXEDOT-2: 전방·후방 고정연장(HHMM, NULL=없음) — 등록범위 피감수 확장(소정 ∪ 고정연장). record(AllowedWindowResult) 끝 4필드와 동일 순서로 SELECT 끝에 둔다(위치 기반 매핑). */ , SCH.PRE_FIXED_OT_STR_TIME AS preFixedOtStrTime , SCH.PRE_FIXED_OT_END_TIME AS preFixedOtEndTime , SCH.FIXED_OT_STR_TIME AS fixedOtStrTime , SCH.FIXED_OT_END_TIME AS fixedOtEndTime
FROM TB_USER_WORK_PLAN WP
/* 근무일(WP.WORK_YMD) 기준 유효 스케줄(effective-dating) 적용. TB_SCH_MGMT(현재본) 은 최신 1건만 보유하므로 과거 버전을 찾지 못한다. TB_SCH_MGMT_HIST(전 버전)를 UNION 으로 합쳐 APPLY_DATE <= WORK_YMD 인 가장 최근 버전의 시간값을 결합한다. (SCH_TYPE 미사용 select 이므로 현재본 추가 조인 불필요) */ LEFT JOIN ( /* 현재본 + 이력본을 SCH_CD + APPLY_DATE 단위로 합친 유효 스케줄 후보. 동일 SCH_CD + APPLY_DATE 가 중복되면 HIST_IDX 최댓값 1건만 채택한다. */ SELECT E.CMPNY_CD , E.SITE_CD , E.SCH_CD , E.APPLY_DATE , E.FST_SCH_STR_TIME , E.FST_SCH_END_TIME , E.FST_SCH_BRK_MIN , E.SEC_SCH_STR_TIME , E.SEC_SCH_END_TIME , E.SEC_SCH_BRK_MIN , E.PRE_FIXED_OT_STR_TIME , E.PRE_FIXED_OT_END_TIME , E.FIXED_OT_STR_TIME , E.FIXED_OT_END_TIME FROM ( /* 현재본 (HIST_IDX 를 최댓값으로 두어 동일 APPLY_DATE 중복 시 현재본 우선) */ SELECT M.CMPNY_CD , M.SITE_CD , M.SCH_CD , M.APPLY_DATE , M.FST_SCH_STR_TIME , M.FST_SCH_END_TIME , M.FST_SCH_BRK_MIN , M.SEC_SCH_STR_TIME , M.SEC_SCH_END_TIME , M.SEC_SCH_BRK_MIN , M.PRE_FIXED_OT_STR_TIME , M.PRE_FIXED_OT_END_TIME , M.FIXED_OT_STR_TIME , M.FIXED_OT_END_TIME , 2147483647 AS HIST_IDX /* 사용중지(USE_YN='N') 근무타입도 이미 배정된 근무일에는 그대로 해석한다 — USE_YN 필터 없음 */ FROM TB_SCH_MGMT M
UNION ALL
/* 이력본 */ SELECT H.CMPNY_CD , H.SITE_CD , H.SCH_CD , H.APPLY_DATE , H.FST_SCH_STR_TIME , H.FST_SCH_END_TIME , H.FST_SCH_BRK_MIN , H.SEC_SCH_STR_TIME , H.SEC_SCH_END_TIME , H.SEC_SCH_BRK_MIN , H.PRE_FIXED_OT_STR_TIME , H.PRE_FIXED_OT_END_TIME , H.FIXED_OT_STR_TIME , H.FIXED_OT_END_TIME , H.HIST_IDX FROM TB_SCH_MGMT_HIST H ) E /* 동일 SCH_CD + APPLY_DATE 그룹에서 HIST_IDX 최댓값 행만 채택 */ WHERE E.HIST_IDX = ( SELECT MAX(E2.HIST_IDX) FROM ( SELECT M2.CMPNY_CD, M2.SITE_CD, M2.SCH_CD, M2.APPLY_DATE, 2147483647 AS HIST_IDX FROM TB_SCH_MGMT M2 UNION ALL SELECT H2.CMPNY_CD, H2.SITE_CD, H2.SCH_CD, H2.APPLY_DATE, H2.HIST_IDX FROM TB_SCH_MGMT_HIST H2 ) E2 WHERE E2.CMPNY_CD = E.CMPNY_CD AND E2.SITE_CD = E.SITE_CD AND E2.SCH_CD = E.SCH_CD AND E2.APPLY_DATE = E.APPLY_DATE ) ) SCH ON SCH.CMPNY_CD = WP.CMPNY_CD AND SCH.SITE_CD = WP.SITE_CD AND SCH.SCH_CD = WP.WORK_PLAN_CD /* 근무일 기준 APPLY_DATE <= WORK_YMD 인 가장 최근(MAX APPLY_DATE) 버전만 적용. 단, 근무일보다 늦게 적용 시작된 스케줄을 그 이전 날에 배정한 경우(상한 충족 버전 없음)엔 "스케줄 없음" 대신 최이른 적용버전(MIN APPLY_DATE)으로 폴백한다. */ AND SCH.APPLY_DATE = ( SELECT COALESCE( MAX(CASE WHEN SE.APPLY_DATE <= WP.WORK_YMD THEN SE.APPLY_DATE END) , MIN(SE.APPLY_DATE) ) FROM ( SELECT M3.CMPNY_CD, M3.SITE_CD, M3.SCH_CD, M3.APPLY_DATE FROM TB_SCH_MGMT M3 UNION ALL SELECT H3.CMPNY_CD, H3.SITE_CD, H3.SCH_CD, H3.APPLY_DATE FROM TB_SCH_MGMT_HIST H3 ) SE WHERE SE.CMPNY_CD = WP.CMPNY_CD AND SE.SITE_CD = WP.SITE_CD AND SE.SCH_CD = WP.WORK_PLAN_CD )
LEFT JOIN TB_USER_ATTD_MGMT A1 ON A1.CMPNY_CD = WP.CMPNY_CD AND A1.SITE_CD = WP.SITE_CD AND A1.USER_CD = WP.USER_CD AND A1.WORK_YMD = WP.WORK_YMD AND A1.WORK_SEQ = 1 AND A1.DEL_YN = 'N'
LEFT JOIN TB_USER_ATTD_MGMT A2 ON A2.CMPNY_CD = WP.CMPNY_CD AND A2.SITE_CD = WP.SITE_CD AND A2.USER_CD = WP.USER_CD AND A2.WORK_YMD = WP.WORK_YMD AND A2.WORK_SEQ = 2 AND A2.DEL_YN = 'N'
WHERE WP.CMPNY_CD = #{gvCmpnyCd} AND WP.SITE_CD = #{siteCd} AND WP.USER_CD = #{userCd} AND WP.WORK_YMD = #{workYmd} LIMIT 1

/* Attd07Mapper.selectActualWindowNoSchedule */
SELECT
      NULL                                                              AS plan1Start
    , NULL                                                              AS plan1End
    , NULL                                                              AS plan2Start
    , NULL                                                              AS plan2End

    /* 1st attd row - raw 출퇴근 일자/시각. */
    , A1.CHECK_IN_DATE                                                 AS act1InDate
    , A1.CHECK_IN_TIME                                                 AS act1InTime
    , A1.CHECK_OUT_DATE                                                AS act1OutDate
    , A1.CHECK_OUT_TIME                                                AS act1OutTime

    /* 2nd attd row - raw 출퇴근 일자/시각. */
    , A2.CHECK_IN_DATE                                                 AS act2InDate
    , A2.CHECK_IN_TIME                                                 AS act2InTime
    , A2.CHECK_OUT_DATE                                                AS act2OutDate
    , A2.CHECK_OUT_TIME                                                AS act2OutTime

    /* PRAFTA-FIXEDOT-2: 스케줄 부재 폴백 — 고정연장도 부재(NULL 4개, record 위치 유지). */
    , NULL                                                             AS preFixedOtStrTime
    , NULL                                                             AS preFixedOtEndTime
    , NULL                                                             AS fixedOtStrTime
    , NULL                                                             AS fixedOtEndTime

/* WP 없이도 항상 1행을 보장하기 위한 dummy anchor.
   스코프(cmpny/site/user/workYmd) 조건은 각 LEFT JOIN 의 ON 절에 직접 명시한다. */
FROM (SELECT 1) D

LEFT JOIN TB_USER_ATTD_MGMT A1
    ON  A1.CMPNY_CD = #{gvCmpnyCd}
    AND A1.SITE_CD  = #{siteCd}
    AND A1.USER_CD  = #{userCd}
    AND A1.WORK_YMD = #{workYmd}
    AND A1.WORK_SEQ = 1
    AND A1.DEL_YN   = 'N'

LEFT JOIN TB_USER_ATTD_MGMT A2
    ON  A2.CMPNY_CD = #{gvCmpnyCd}
    AND A2.SITE_CD  = #{siteCd}
    AND A2.USER_CD  = #{userCd}
    AND A2.WORK_YMD = #{workYmd}
    AND A2.WORK_SEQ = 2
    AND A2.DEL_YN   = 'N'

LIMIT 1

/* Attd07Mapper.selectLeaveExemptWindows */
SELECT DISTINCT
      L.START_DATE  AS startDate
    , L.START_TIME  AS startTime
    , L.END_DATE    AS endDate
    , L.END_TIME    AS endTime
FROM TB_USER_LEAVE_USE L
WHERE L.CMPNY_CD      = #{cmpnyCd}
  AND L.SITE_CD       = #{siteCd}
  AND L.USER_CD       = #{userCd}
  AND L.START_DATE    = #{workYmd}
  AND L.LEAVE_STATUS  = 'CONFIRMED'
  AND L.DEL_YN        = 'N'
  AND L.USE_UNIT_TYPE IN ('01', '02', '03', '04')
  AND L.START_TIME IS NOT NULL
  AND L.END_TIME   IS NOT NULL

/* Attd07Mapper.selectOtId */
SELECT CONCAT(DATE_FORMAT(NOW(), '%Y%m%d'), FNC_CMM_SEQ_NEXTVAL(#{gvCmpnyCd}, 'OT_ID')) AS otId
FROM DUAL

/* Attd07Mapper.selectUserExistInCmpnySite - SEC-017 scope check */
SELECT COUNT(*)
FROM TB_USER U
WHERE U.CMPNY_CD        = #{cmpnyCd}
  AND U.SITE_CD         = #{siteCd}
  AND U.USER_CD         = #{userCd}
  AND U.USE_YN          = 'Y'
  AND U.WITHDRAWAL_DATE IS NULL

/* Attd07Mapper.selectDailyWorkerInScope - 일용직 OT 등록 차단 */
SELECT COUNT(*)
FROM TB_USER U
WHERE U.CMPNY_CD        = #{cmpnyCd}
  AND U.SITE_CD         = #{siteCd}
  AND U.USER_CD         = #{userCd}
  AND U.EMPLOYMENT_TYPE = 'DAILY'

/* Attd07Mapper.selectAttdExistInScope - SEC-017 scope check */
SELECT COUNT(*)
FROM TB_USER_ATTD_MGMT M
WHERE M.CMPNY_CD = #{cmpnyCd}
  AND M.SITE_CD  = #{siteCd}
  AND M.USER_CD  = #{userCd}
  AND M.ATTD_ID  = #{attdId}
  AND M.DEL_YN   = 'N'

/* Attd07Mapper.selectOverlappingOvertimeCount - PRAFTA-009-001 OT overlap check */
SELECT COUNT(*)
FROM TB_USER_OVERTIME_MGMT O
WHERE O.CMPNY_CD = #{cmpnyCd}
  AND O.SITE_CD  = #{siteCd}
  AND O.USER_CD  = #{userCd}
  AND O.ATTD_ID  = #{attdId}
  AND O.ACTUAL_END_DATE IS NOT NULL
  AND O.ACTUAL_END_TIME IS NOT NULL
  AND CONCAT(O.ACTUAL_START_DATE, O.ACTUAL_START_TIME)  <  #{reqEnd}
  AND #{reqStart}  <  CONCAT(O.ACTUAL_END_DATE, O.ACTUAL_END_TIME)
  AND O.DEL_YN    = 'N'
  AND O.OT_STATUS  <>  'CANCELLED'


  AND O.OT_ID NOT IN
  #{exId}

/* Attd07Mapper.countActiveOvertimeOutsideAttdWindow - OT must stay within new attd window */
SELECT COUNT(*)
FROM TB_USER_OVERTIME_MGMT O
WHERE O.CMPNY_CD = #{cmpnyCd}
  AND O.SITE_CD  = #{siteCd}
  AND O.USER_CD  = #{userCd}
  AND O.ATTD_ID  = #{attdId}
  AND O.DEL_YN   = 'N'
  AND O.OT_STATUS  <>  'CANCELLED'
  AND (
    CONCAT(O.ACTUAL_START_DATE, O.ACTUAL_START_TIME)  <  #{newStart}
    OR O.ACTUAL_END_DATE IS NULL
    OR O.ACTUAL_END_TIME IS NULL



        OR 1 = 1


        OR CONCAT(O.ACTUAL_END_DATE, O.ACTUAL_END_TIME)  >  #{newEnd}


  )

mapper.insert:
/* Attd07Mapper.insertUserOvertime */
INSERT INTO TB_USER_OVERTIME_MGMT (
      OT_ID
    , CMPNY_CD
    , SITE_CD
    , USER_CD

    , ATTD_ID
    , REQ_ID

    , WORK_YMD
    , NODE_CD

    , PLAN_START_DATE
    , PLAN_START_TIME
    , PLAN_END_DATE
    , PLAN_END_TIME

    , ACTUAL_START_DATE
    , ACTUAL_START_TIME
    , ACTUAL_END_DATE
    , ACTUAL_END_TIME

    , WORK_MINUTES
    , BREAK_MINUTES

    , OT_STATUS

    , DEL_YN
    , INSERT_NO
    , INSERT_DATE
)
VALUES (
      #{otId}
    , #{gvCmpnyCd}
    , #{siteCd}
    , #{userCd}

    , #{attdId}
    , #{reqId}

    , #{workYmd}
    , #{nodeCd}

    , #{planStartDate}
    , #{planStartTime}
    , #{planEndDate}
    , #{planEndTime}

    , #{actualStartDate}
    , #{actualStartTime}
    , #{actualEndDate}
    , #{actualEndTime}

    , #{workMinutes}
    , #{breakMinutes}

    , #{otStatus}

    , 'N'
    , #{gvUserCd}
    , NOW()
)

mapper.update:
/* Attd07Mapper.updateUserOvertimeModify - PRAFTA-025 초과근무 수정 승인 */
UPDATE TB_USER_OVERTIME_MGMT
   SET PLAN_START_DATE   = #{startDate}
     , PLAN_START_TIME   = #{startTime}
     , PLAN_END_DATE     = #{endDate}
     , PLAN_END_TIME     = #{endTime}
     , ACTUAL_START_DATE = #{startDate}
     , ACTUAL_START_TIME = #{startTime}
     , ACTUAL_END_DATE   = #{endDate}
     , ACTUAL_END_TIME   = #{endTime}
     , WORK_MINUTES      = #{workMinutes}
     , UPDATE_NO         = #{updateNo}
     , UPDATE_DATE       = NOW()
 WHERE CMPNY_CD   = #{cmpnyCd}
   AND SITE_CD    = #{siteCd}
   AND USER_CD    = #{userCd}
   AND OT_ID      = #{otId}
   AND DEL_YN     = 'N'
   AND OT_STATUS  <>  'CANCELLED'

/* Attd07Mapper.updateUserOvertimeDirect - com-013-06 A 관리자 직접수정 in-place UPDATE */
UPDATE TB_USER_OVERTIME_MGMT
   SET PLAN_START_DATE   = #{startDate}
     , PLAN_START_TIME   = #{startTime}
     , PLAN_END_DATE     = #{endDate}
     , PLAN_END_TIME     = #{endTime}
     , ACTUAL_START_DATE = #{startDate}
     , ACTUAL_START_TIME = #{startTime}
     , ACTUAL_END_DATE   = #{endDate}
     , ACTUAL_END_TIME   = #{endTime}
     , WORK_MINUTES      = #{workMinutes}
     , UPDATE_NO         = #{updateNo}
     , UPDATE_DATE       = NOW()
 WHERE CMPNY_CD   = #{cmpnyCd}
   AND SITE_CD    = #{siteCd}
   AND USER_CD    = #{userCd}
   AND OT_ID      = #{otId}
   AND ATTD_ID    = #{attdId}
   AND DEL_YN     = 'N'
   AND OT_STATUS  <>  'CANCELLED'

mapper.select:
/* Attd07Mapper.selectWeeklyOvertimeMinutes - 소정-07 단축근무자 주간 초과근무 합계(사업장 무관) */
SELECT
    (
        SELECT IFNULL(SUM(O.WORK_MINUTES), 0)
          FROM TB_USER_OVERTIME_MGMT O
         WHERE O.CMPNY_CD  = #{cmpnyCd}
           AND O.USER_CD   = #{userCd}
           AND O.WORK_YMD  BETWEEN #{weekStartYmd} AND #{weekEndYmd}
           AND O.DEL_YN    = 'N'
           AND O.OT_STATUS  <>  'CANCELLED'

           AND O.OT_ID NOT IN
           #{exOtId}

    )
    +
    (
        SELECT IFNULL(SUM(
                   GREATEST(
                       TIMESTAMPDIFF(MINUTE
                           , STR_TO_DATE(CONCAT(R.START_DATE, R.START_TIME), '%Y%m%d%H%i')
                           , STR_TO_DATE(CONCAT(R.END_DATE,   R.END_TIME),   '%Y%m%d%H%i'))
                     , 0)
               ), 0)
          FROM TB_USER_ATTD_REQ R
         WHERE R.CMPNY_CD   = #{cmpnyCd}
           AND R.USER_CD    = #{userCd}
           AND R.WORK_YMD   BETWEEN #{weekStartYmd} AND #{weekEndYmd}
           AND R.REQ_TYPE   IN ('03', '04')
           AND R.REQ_STATUS = '01'
           AND R.DEL_YN     = 'N'
           AND R.START_DATE IS NOT NULL
           AND R.START_TIME IS NOT NULL
           AND R.END_DATE   IS NOT NULL
           AND R.END_TIME   IS NOT NULL

           AND R.REQ_ID  <>  #{excludeReqId}

    ) AS weeklyOtMinutes
